B.aP9=new A.e8("chief","Chief Ouru","village_chief",7,3,12,B.aG1,"eastGateOpen",B.aFC,"questDone:warchief",B.apB,!0,!1,!1,!1,B.KK,"mage","chief_ouru","chief_ouru_happy",null,null)
B.axK=s(["Hold still. This salve stings.","Another one from the east. The wounds are deep.","Drink first. Then tell me what you saw out there."],t.s)
B.aPn=new A.e8("healer","Healer Mira","village_healer",4,3,12,B.axK,null,null,null,null,!0,!1,!1,!0,null,"priest",null,null,"healer",null)
B.avi=s(["Are you a warrior? Mum says orcs eat children.","I drew an orc. It is very ugly.","Uncle says the orcs will come back this year."],t.s)
B.aPl=new A.e8("child","Tali","village_family",9,3,12,B.avi,null,null,null,null,!0,!1,!1,!1,null,"adventurer",null,null,"child",null)
B.anG=s(["The deer ran east. Strange for deer.","Watch the tree line when you go out.","My bow is strung. Always."],t.s)
B.aPc=new A.e8("hunter","Hunter Dahk","village",20,15,12,B.anG,null,null,null,null,!0,!1,!1,!1,null,"archer",null,null,"hunter",null)
B.av9=s(["I remember when the east was only forest.","Fire keeps the bad things away. Mostly."],t.s)
B.aPb=new A.e8("elder","Elder Sohn","village",31,34,12,B.av9,null,null,null,null,!0,!1,!1,!1,null,"mage",null,null,"marl","sohn_scene")
B.aCb=s(["Sit, sit! Best salve in the world, this.","Two more weeks and I am back out there."],t.s)
B.aPs=new A.e8("ansa","Ansa","village",27,23,22,B.aCb,null,null,null,null,!0,!1,!1,!1,null,"adventurer",null,null,"healer","ansa_scene")
B.asc=s(["The gate is closed for now.","We doubled the watch since the smoke rose.","Nothing comes through here without the chief."],t.s)
B.axe=s(["The chief opened the way. Watch yourself out there."],t.s)
B.aP2=new A.e8("guard","Guard Brek","village",66,35,12,B.asc,"eastGateOpen",B.axe,null,null,!0,!1,!1,!1,null,"sword",null,null,"child","brek_scene")
B.aFp=s(["I came back from the east. Do not ask.","Those were not hunters' fires out there.","Let me rest. My arm still bleeds."],t.s)
B.aPa=new A.e8("scout","Scout Ilun","village",24,20,12,B.aFp,null,null,null,null,!0,!1,!1,!1,null,"archer",null,null,"scout",null)
B.aj3=s(["Courier Pell, fastest legs in the village!","Letters, parcels, secrets. Well. Letters."],t.s)
B.aP0=new A.e8("pell","Courier Pell","village",63,37,15,B.aj3,null,null,null,null,!0,!1,!1,!1,null,"adventurer",null,null,"pell",null)
B.awI=s(["I will shape tools here once my bench is set.","Bring me hide and bone and I will work them."],t.s)
